SELECT MONTH(opened_date) AS opened_month, ROUND((100 * SUM(CASE WHEN city = 'Singapore' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_singapore, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(region))) AS region_values, MAX(sqft) AS max_sqft FROM stores WHERE city IN ('New York', 'Chiang Mai', 'Berlin') AND opened_date BETWEEN '2024-10-23' AND '2025-09-27' GROUP BY MONTH(opened_date) HAVING MAX(sqft) > 13200 ORDER BY 4
